export function buildHelpView(category='start') {
  const current=HELP_CATEGORIES[category] ?? HELP_CATEGORIES.start;
  const menu=new StringSelectMenuBuilder().setCustomId('yachiyo_help_category').setPlaceholder('Choose a command category').addOptions(Object.entries(HELP_CATEGORIES).map(([value,item])=>({label:item.label,value,description:item.description,default:value===category})));
  return {embeds:[new EmbedBuilder().setColor(0xf3a6c7).setTitle('YACHIYO COMMAND CENTER').setDescription(current.body).setFooter({text:'Choose a category below to explore Yachiyo’s commands.'})],components:[new ActionRowBuilder().addComponents(menu)]};
}
