    if(active) return interaction.reply({content:'A Quiz Bee is already active in this channel. Join it from the panel below.',ephemeral:true});
    const session=await createQuiz({guildId:interaction.guildId,channelId:interaction.channelId,hostId:interaction.user.id,rounds:interaction.options.getInteger('rounds')??10,difficulty:interaction.options.getString('difficulty')??'mixed',topic:(interaction.options.getString('topic')||'random').toLowerCase()});
    return interaction.reply({embeds:[yEmbed('☾ QUIZ BEE LOBBY',`Host: <@${session.host_id}>\nRounds: **${session.rounds}**\nDifficulty: **${session.difficulty}**\nTopic: **${session.topic}**\n\nJoin the game below, then the host can begin the first round.`)],components:[new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId('quiz_join:'+session.id).setLabel('Join Quiz').setStyle(ButtonStyle.Primary),new ButtonBuilder().setCustomId('quiz_start:'+session.id).setLabel('Start Quiz').setStyle(ButtonStyle.Success),new ButtonBuilder().setCustomId('quiz_stop:'+session.id).setLabel('Stop Quiz').setStyle(ButtonStyle.Danger))]});
