  if (name==='daily-question') return interaction.reply({embeds:[yEmbed('☾ DAILY QUESTION','If you could instantly master one school subject, which would you choose and why?',0xf3a6c7)],components:[new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId('daily_question_next').setLabel('New Question').setStyle(ButtonStyle.Secondary))]});
  if (name==='rate') { const user=interaction.options.getUser('user'); if(user.id===interaction.user.id) return interaction.reply({content:'You are already wonderful without a rating. ♡',ephemeral:true}); const categories=[['Vibe',70,99],['Kindness',75,100],['Creativity',65,100],['Energy',70,98]], lines=categories.map(([label,min,max])=>`${label}: **${Math.floor(Math.random()*(max-min+1))+min}/100**`); return interaction.reply({embeds:[yEmbed('✦ PLAYFUL MEMBER RATING',`A completely non-serious rating for ${user}.\n\n${lines.join('\n')}\n\n♡ Just for fun—no sensitive traits are rated.`,0xf3a6c7)]}); }
  const disabledEconomyCommands = new Set(['balance','daily','work','fish','economy-add','admin-abuse','pay','deposit','withdraw','leaderboard','level','fish-setup','fishinventory','fishalmanac','give','gamble','rob','fishprofile','fishleaderboard','server-shop','server-inventory','fishshop','fishrod','fishstatuseffects','fishdrink','fishmarket','fishaquarium','fishbattle','fishbattlepvp']);
  if (disabledEconomyCommands.has(name)) return interaction.reply({content:'This economy and fishing feature has moved to Kaguya-App.',ephemeral:true});
